// B2 Churn Radar — Risk Scoring Engine
// Inputs: rows from Google Sheets (active customers only)
// Outputs: one item per customer that needs action this run

const rows = $input.all();
const now = new Date();
const results = [];

for (const row of rows) {
  const d = row.json;

  // Skip rows missing critical fields
  if (!d['Customer Email'] || !d['Last Purchase Date']) continue;

  const lastPurchase = new Date(d['Last Purchase Date']);
  if (isNaN(lastPurchase.getTime())) continue;

  const daysSince = Math.floor((now - lastPurchase) / 86400000);
  const freqDays = parseInt(d['Purchase Frequency Days']) || 30;
  const churnRatio = daysSince / freqDays;
  const totalPurchases = parseInt(d['Total Purchases']) || 1;
  const avgSpend = parseFloat(d['Average Spend']) || 0;

  // Loyalty multiplier — repeat customers get earlier intervention
  const loyaltyWeight = totalPurchases >= 10 ? 1.2 : totalPurchases >= 5 ? 1.1 : 1.0;
  const adjustedRatio = churnRatio * loyaltyWeight;

  let riskLevel = 'Low';
  if (adjustedRatio >= 2.0) riskLevel = 'Critical';
  else if (adjustedRatio >= 1.5) riskLevel = 'High';
  else if (adjustedRatio >= 1.2) riskLevel = 'Medium';

  // Auto-recovery detection — if customer purchased recently, mark recovered
  if (daysSince < freqDays * 0.5 && (d['Sequence Stage'] || 'None') !== 'None') {
    results.push({
      action: 'recovered',
      customerName: d['Customer Name'],
      customerEmail: d['Customer Email'],
      businessName: d['Business Name'],
      ownerEmail: d['Owner Email'],
      daysSince,
      churnRatio: churnRatio.toFixed(2),
      riskLevel: 'Low',
      newStatus: 'Recovered',
      avgSpendFormatted: 'R' + avgSpend.toLocaleString('en-ZA', { minimumFractionDigits: 2 })
    });
    continue;
  }

  // Only act on Medium+ risk
  if (riskLevel === 'Low') continue;

  // Cadence check — don't email same customer twice in 3 days
  const lastContactedRaw = d['Last Contacted'] || '';
  const lastContacted = lastContactedRaw ? new Date(lastContactedRaw) : null;
  const daysSinceContact = lastContacted && !isNaN(lastContacted.getTime())
    ? Math.floor((now - lastContacted) / 86400000)
    : 999;

  // Determine sequence stage progression
  const currentStage = d['Sequence Stage'] || 'None';
  let nextStage = currentStage;
  let shouldEmail = false;

  if (currentStage === 'None') {
    nextStage = 'Stage 1 — Soft Check-In';
    shouldEmail = true;
  } else if (currentStage === 'Stage 1 — Soft Check-In' && daysSinceContact >= 3) {
    nextStage = 'Stage 2 — Value Reminder';
    shouldEmail = true;
  } else if (currentStage === 'Stage 2 — Value Reminder' && daysSinceContact >= 4) {
    nextStage = 'Stage 3 — Final Offer';
    shouldEmail = true;
  } else if (currentStage === 'Stage 3 — Final Offer' && daysSinceContact >= 14 && riskLevel === 'Critical') {
    // Mark as Lost after 14 more days post-Stage 3 with no recovery
    results.push({
      action: 'lost',
      customerName: d['Customer Name'],
      customerEmail: d['Customer Email'],
      businessName: d['Business Name'],
      ownerEmail: d['Owner Email'],
      daysSince,
      churnRatio: churnRatio.toFixed(2),
      riskLevel,
      newStatus: 'Lost',
      avgSpendFormatted: 'R' + avgSpend.toLocaleString('en-ZA', { minimumFractionDigits: 2 })
    });
    continue;
  }

  if (!shouldEmail) continue;

  results.push({
    action: 'engage',
    customerName: d['Customer Name'],
    customerEmail: d['Customer Email'],
    businessName: d['Business Name'],
    ownerEmail: d['Owner Email'],
    lastPurchaseDate: d['Last Purchase Date'],
    purchaseFrequency: freqDays,
    averageSpend: avgSpend,
    totalPurchases,
    daysSince,
    churnRatio: churnRatio.toFixed(2),
    riskLevel,
    currentStage,
    nextStage,
    emailsSent: parseInt(d['Emails Sent']) || 0,
    avgSpendFormatted: 'R' + avgSpend.toLocaleString('en-ZA', { minimumFractionDigits: 2 }),
    runAt: $now.setZone('Africa/Johannesburg').toFormat('yyyy-MM-dd HH:mm:ss')
  });
}

// If nothing to do, emit a single sentinel item
if (!results.length) {
  return [{ json: { hasAtRisk: false, action: 'none', count: 0, message: 'No churn action needed today.' } }];
}

return results.map(r => ({ json: { hasAtRisk: true, count: results.length, ...r } }));

