const promptVersion = 'b2-engage-v1';
// B2 Churn Radar — AI Response Parser
// Pulls JSON out of the AI text, falls back safely on failure

const rawText = $input.item.json['rawAIText'] || '';

const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleanedText);
} catch (e) {
  // Try to extract first JSON object if model wrapped it
  const match = cleanedText.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); }
    catch (e2) {
      parsed = {
        subject: 'Checking in from ' + ($input.item.json['businessName'] || 'us'),
        body: 'Hi there, just dropping by to say hello and to thank you for your support. If there is anything we can do for you, just hit reply. — ' + ($input.item.json['businessName'] || ''),
        tone_used: 'Fallback'
      };
    }
  } else {
    parsed = {
      subject: 'Checking in from ' + ($input.item.json['businessName'] || 'us'),
      body: 'Hi there, just dropping by to say hello and to thank you for your support. If there is anything we can do for you, just hit reply. — ' + ($input.item.json['businessName'] || ''),
      tone_used: 'Fallback'
    };
  }
}

const d = $input.item.json;

// Extract first name
const fullName = d['customerName'] || 'there';
const firstName = fullName.split(' ')[0] || 'there';

// Risk styling
let borderColor = '#22d3ee';
let riskEmoji = '🔵';
if (d['riskLevel'] === 'Critical') { borderColor = '#f43f5e'; riskEmoji = '🔴'; }
else if (d['riskLevel'] === 'High') { borderColor = '#f97316'; riskEmoji = '🟠'; }
else if (d['riskLevel'] === 'Medium') { borderColor = '#f59e0b'; riskEmoji = '🟡'; }

return { promptVersion,
  subject: parsed['subject'] || ('Hey ' + firstName + ' — checking in from ' + d['businessName']),
  body: parsed['body'] || 'Hi there, just dropping by. — ' + d['businessName'],
  toneUsed: parsed['tone_used'] || 'Warm',
  parseSuccess: parsed['tone_used'] !== 'Fallback',
  customerName: d['customerName'],
  customerEmail: d['customerEmail'],
  firstName,
  businessName: d['businessName'],
  ownerEmail: d['ownerEmail'],
  riskLevel: d['riskLevel'],
  daysSince: d['daysSince'],
  nextStage: d['nextStage'],
  emailsSent: parseInt(d['emailsSent']) || 0,
  avgSpendFormatted: d['avgSpendFormatted'],
  borderColor,
  riskEmoji,
  runAt: $now.setZone('Africa/Johannesburg').toFormat('yyyy-MM-dd HH:mm:ss')
};

