// B2 Churn Radar — Weekly Aggregator

const rows = $input.all();
const total = rows.length;

const byRisk = (level) => rows.filter(r => (r.json['Risk Level'] || '').trim() === level).length;
const byStatus = (status) => rows.filter(r => (r.json['Status'] || '').trim() === status).length;

const critical = byRisk('Critical');
const high = byRisk('High');
const medium = byRisk('Medium');
const low = byRisk('Low');
const active = byStatus('Active');
const recovered = byStatus('Recovered');
const lost = byStatus('Lost');

const emailsSentTotal = rows.reduce((acc, r) => acc + (parseInt(r.json['Emails Sent']) || 0), 0);

const atRiskRevenue = rows
  .filter(r => ['Critical', 'High'].includes((r.json['Risk Level'] || '').trim()))
  .reduce((acc, r) => acc + (parseFloat(r.json['Average Spend']) || 0), 0);

const recoveredRevenue = rows
  .filter(r => (r.json['Status'] || '').trim() === 'Recovered')
  .reduce((acc, r) => acc + (parseFloat(r.json['Average Spend']) || 0), 0);

const formatRand = n => 'R' + n.toLocaleString('en-ZA', { minimumFractionDigits: 2 });

const summary = [
  'Total customers monitored: ' + total,
  'Active: ' + active,
  'Critical risk: ' + critical,
  'High risk: ' + high,
  'Medium risk: ' + medium,
  'Low risk: ' + low,
  'Recovered: ' + recovered + ' (worth ' + formatRand(recoveredRevenue) + ')',
  'Lost: ' + lost,
  'Re-engagement emails sent total: ' + emailsSentTotal,
  'Revenue at risk: ' + formatRand(atRiskRevenue)
].join('. ');

return [{
  json: {
    total, active,
    critical, high, medium, low,
    recovered, lost,
    emailsSentTotal,
    atRiskRevenue: formatRand(atRiskRevenue),
    recoveredRevenue: formatRand(recoveredRevenue),
    summary,
    reportDate: new Date().toLocaleDateString('en-ZA', { timeZone: 'Africa/Johannesburg' })
  }
}];

