// Code — Enrich With Tier (B10 lookup → tier-aware payload)
// Defensive: handles unfound customer (Bronze/Unknown defaults)
function trimKeys(o){ const r={}; for(const k in o){ r[k.trim()]=o[k]; } return r; }

const upstream = $('Code — Risk Scorer').item.json;
const raw = $input.all().map(i => trimKeys(i.json || {}));
const found = raw.find(r => r['Customer Name']) || {};

let tier = 'Unknown';
let lifetimeValue = 0;
let totalPurchases = 0;
let trajectory = 'unknown';
let lastProduct = '';

if (found['Customer Name']) {
  tier = found['Tier'] || 'Bronze';
  lifetimeValue = parseFloat(found['Lifetime Value'] || found['Total Spend'] || 0);
  totalPurchases = parseInt(found['Total Purchases'] || 0);
  trajectory = found['Trajectory'] || 'stable';
  lastProduct = found['Last Product'] || '';
}

const isVIP = tier === 'VIP';
const isHighValue = tier === 'VIP' || tier === 'Gold';
const knownCustomer = tier !== 'Unknown';

const formatRand = n => 'R' + (parseFloat(n) || 0).toLocaleString('en-ZA');

return [{
  json: {
    ...upstream,
    tier,
    isVIP,
    isHighValue,
    knownCustomer,
    lifetimeValue,
    lifetimeValueFormatted: formatRand(lifetimeValue),
    totalPurchases,
    trajectory,
    lastProduct
  }
}];

